          const b = a + Math.PI * (0.6 + this.r() * 0.8), pts = [V3(x0, -0.2, z0), V3(x0 + Math.cos(b) * 0.5, h * 0.35, z0 + Math.sin(b) * 0.5), V3(x0 - Math.cos(b) * 0.3, h * 0.7, z0 - Math.sin(b) * 0.3), V3(x0 + Math.cos(a) * 0.4, h, z0 + Math.sin(a) * 0.4)];
