  // zone.timeShift：時の水晶（{ id, crystals: [[x, z, 向き], ...], after }。向きは 'W' 白：どちらへも、'P' 金：昔へだけ、'N' 青：今へだけ）。地図の R のマスは、今は瓦礫（昔はまだ崩れていない）、
  //   A のマスは、昔は石の壁や門（今は崩れて、根もとだけ残っている）。水晶にふれると、遺跡が「今」と「昔」で切りかわる（FieldView.touchTime）。
