      const [x0, z0] = pts[i - 1], [x1, z1] = pts[i], len = Math.hypot(x1 - x0, z1 - z0), n = Math.floor(len / 0.8);
      const fx = (x1 - x0) / len, fz = (z1 - z0) / len, nx = -fz, nz = fx;
