    const barkC = new THREE.Color('#7a5838'), barkD = new THREE.Color('#5e4430'), mossC = new THREE.Color('#5f8f3c'), mossD = new THREE.Color('#41702c'), dullC = new THREE.Color('#7e8270'), dullD = new THREE.Color('#686c5c');
