      if (r() < 0.6) { const b = at(L * 0.5, 2), d2 = d.clone().applyAxisAngle(V3(0, 1, 0), (r() < 0.5 ? 1 : -1) * (0.5 + r() * 0.4)); tube([b, b.clone().addScaledVector(d2, 10).setY(y0 + 1.2), b.clone().addScaledVector(d2, 20 + r() * 8).setY(y0 - 1)], 2.2, 0.5, 1.4, 12); }
