      const a = this.r() * Math.PI * 2, d = Math.sqrt(this.r()) * r, px = x + Math.cos(a) * d, pz = z + Math.sin(a) * d, y = this.gy(px, pz) + y0, h = 0.22 + this.r() * 0.18;
      stem.box(px - 0.008, y, pz - 0.008, px + 0.008, y + h, pz + 0.008);
