      const tilt = 0.35 + this.r() * 0.45, ta = this.r() * Math.PI * 2, nrm = V3(Math.sin(tilt) * Math.cos(ta), Math.cos(tilt), Math.sin(tilt) * Math.sin(ta));
      plate(heads[i % cols.length], V3(px, y + h, pz), nrm, 0.08 + this.r() * 0.03, this.r() * Math.PI * 2);
