    this.mg(rim, lathe([[0, 0.2], [0.75, 0.2], [0.75, 0.42], [0.55, 0.55], [0.45, 0.75], [0.45, 1.25], [0.6, 1.35], [0.62, 1.48], [0, 1.48]], 24), x, y0, z);
    this.mg(trim, new THREE.TorusGeometry(0.47, 0.035, 6, 24), x, y0 + 1.0, z, [Math.PI / 2, 0, 0]);
