    for (const sd of [-1, 1]) for (const z of [-16, 0]) K.banner(sd * 13.61, z, -sd * Math.PI / 2, 6.0, 3.0, clothC, '#ffd27a', 0.8);
    for (const sd of [-1, 1]) for (const z of [-4, 3]) sconce(sd * 13.9, z, -sd * Math.PI / 2);
