    for (let i = 0; i < 6; i++) K.mesh(new THREE.BoxGeometry(0.3, 0.02, 0.18), pick(['#ff9ad8', '#ffd27a', '#8ad8ff']), -22.4 + i * 0.5, 1.22, -32.2 + (K.r() - 0.5) * 0.3, { ry: K.r(), noShadow: true });
    K.crate(-17.5, -24); K.crate(-18.6, -24.4, 0.8); K.barrel(-31, -24);
