    K.paper(-23.9, -33, Math.PI / 2, 'ブランコ', ['出番は', 'いちばん', 'はじめ！'], { bg: '#e8f0ff', ink: '#3a5aa0', w: 1.0 });
    K.paper(-39.9, -9, Math.PI / 2, 'つなわたり', ['出番は', '玉のりより', 'あと'], { bg: '#f0ffe8', ink: '#3a7a4a', w: 1.0 });
